<template><view class="page"><view class="card"><view class="title">绑定健康设备</view><input v-model="form.deviceSn" placeholder="设备编号"/><input v-model="form.bindCode" password placeholder="设备绑定码"/><button @tap="bind">确认绑定</button></view><view class="title list-title">我的设备</view><view v-for="item in list" :key="item.id" class="card device"><view><b>{{item.deviceModel||item.deviceType}}</b><text>{{item.deviceSn}}</text><text>{{item.status==='ACTIVE'?'已绑定':'已解绑'}}</text></view><button v-if="item.status==='ACTIVE'" size="mini" @tap="unbind(item)">解绑</button></view><view v-if="!list.length" class="empty">暂无绑定设备</view></view></template><script>import{getHealthDevices,bindHealthDevice,unbindHealthDevice}from'@/api/health.js';export default{data(){return{form:{deviceSn:'',bindCode:''},list:[]}},onShow(){this.load()},methods:{load(){getHealthDevices().then(r=>this.list=(r&&r.data)||r||[])},bind(){if(!this.form.deviceSn||!this.form.bindCode)return uni.showToast({title:'请填写设备编号和绑定码',icon:'none'});bindHealthDevice(this.form).then(()=>{uni.showToast({title:'绑定成功'});this.form={deviceSn:'',bindCode:''};this.load()})},unbind(item){uni.showModal({title:'确认解绑',success:r=>{if(r.confirm)unbindHealthDevice(item.id,'用户主动解绑').then(()=>this.load())}})}}}</script><style lang="scss" scoped>.page{min-height:100vh;background:#f6f7f8;padding:24rpx}.card{background:#fff;border-radius:20rpx;padding:26rpx;margin-bottom:18rpx}.title{font-size:31rpx;font-weight:600;margin-bottom:20rpx}.list-title{margin:32rpx 8rpx 18rpx}.card input{height:84rpx;border-bottom:1rpx solid #eee}.card button{margin-top:24rpx;background:#19bf9b;color:#fff}.device{display:flex;justify-content:space-between;align-items:center}.device text{display:block;color:#999;font-size:23rpx;margin-top:7rpx}.device button{margin:0;background:#fff;color:#d55;border:1rpx solid #ddd}.empty{text-align:center;padding:80rpx;color:#aaa}</style>